fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    // Since the array is sorted, duplicates appear consecutively.
    // We count unique values by scanning once and counting when the current element differs from the previous.
    let mut count = 1; // First element is always unique if array is not empty.
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            count += 1;
        }
    }

    count
}